#include <bits/stdc++.h>
int main(int c, char** v) { std::mt19937 r(atoi(v[1])); int n = r() % 7 + 2; std::vector<std::array<int,3>> e; for (int i = 2; i <= n; i++) e.push_back({int(r() % (i - 1) + 1), i, int(r() % 5 + 1)}); int extra = r() % 5; while (extra--) { int a = r() % n + 1, b = r() % n + 1; if (a != b) e.push_back({a, b, int(r() % 5 + 1)}); } std::shuffle(e.begin(), e.end(), r); int k = r() % (int)e.size(); printf("%d %d %d\n", n, (int)e.size(), k); for (auto [a, b, w] : e) printf("%d %d %d\n", a, b, w); }
